// Source fixtures: circuitpython-source/src/apps/Orion/modules/drop.py and
// randomize.py with core/utils.py (hash_u32, random_float, random_int) and
// core/music.py (transpose). Expected traces were generated by running that
// source logic with the real utils/music helpers under python -I.
#include "domain/modules/registry.hpp"
#include "domain/modules/drop_randomize.hpp"
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <initializer_list>

namespace {
using namespace orbit;

std::uint32_t g_seed = 0;
std::uint32_t next_counter(void* ctx) {
  return ++*static_cast<std::uint32_t*>(ctx);
}

bool equal(const char* a, const char* b) { return std::strcmp(a, b) == 0; }

ProcessContext make_context(const GlobalState& global, const TransportView& view, RandomSource& random) {
  return ProcessContext{{0, 0}, global, view, random};
}

void add_note(NoteBuffer& buffer, std::uint8_t pitch, std::uint8_t velocity, std::uint8_t channel) {
  assert(buffer.append({pitch, velocity, channel}) == PushResult::Added);
}

void expect_on(const NoteBuffer& buffer, std::initializer_list<Note> expected) {
  assert(static_cast<std::size_t>(buffer.count) == expected.size());
  std::size_t i = 0;
  for (const auto& note : expected) {
    assert(buffer.items[i].pitch == note.pitch);
    assert(buffer.items[i].velocity == note.velocity);
    assert(buffer.items[i].channel == note.channel);
    ++i;
  }
}

void expect_pitches(const NoteBuffer& buffer, std::initializer_list<std::uint8_t> pitches) {
  assert(static_cast<std::size_t>(buffer.count) == pitches.size());
  std::size_t i = 0;
  for (const auto pitch : pitches) assert(buffer.items[i++].pitch == pitch);
}

void test_hash_matches_source() {
  // utils.hash_u32 and random_float golden values from the source.
  assert(seeded::hash_u32(0) == 3221834090U);
  assert(seeded::hash_u32(1) == 656419997U);
  assert(seeded::hash_u32(6) == 1908582930U);
  assert(seeded::hash_u32(100) == 1937382474U);
  assert(seeded::hash_u32(101) == 3743452803U);
  assert(seeded::hash_u32(12345) == 2301815827U);
  assert(seeded::hash_u32(4294967295ULL) == 1368758739U);
  assert(seeded::hash_u32(4294967303ULL) == 2274502692U);
  assert(seeded::random_float(0) == 3221834090.0 / 4294967296.0);
  // utils.random_int golden values: (seed, max, mode) -> value.
  // Rows: seed, then (max 3, mode 0), (max 3, mode 1), (max -4, mode 0).
  struct RandomIntCase { std::uint64_t seed; std::int64_t a, b, c; };
  const RandomIntCase cases[] = {
      {0, 2, 3, -4}, {5, 1, -3, -1}, {100, 2, 3, 0},
      {200, 3, 3, -2}, {300, 1, 2, -1}, {400, 2, 2, -1}, {600, 3, 1, -4}};
  for (const auto& row : cases) {
    assert(seeded::random_int(row.seed, 3, 0) == row.a);
    assert(seeded::random_int(row.seed, 3, 1) == row.b);
    assert(seeded::random_int(row.seed, -4, 0) == row.c);
  }
}

void test_drop_descriptor() {
  const auto* drop = find_module("drop");
  const auto* randomize = find_module("randomize");
  assert(drop && randomize && !find_module("phraser"));
  assert(module_count() == 18);
  assert(module_at(7) == drop && module_at(13) == randomize);
  assert(drop->version == 1 && drop->param_count == 4);
  assert(equal(drop->params[0].name, "drop") && drop->params[0].default_value.value.integer == 0);
  assert(drop->params[0].minimum.value.integer == 0 && drop->params[0].maximum.value.integer == 100);
  assert(drop->params[0].step.value.integer == 5);
  assert(equal(drop->params[1].name, "mode") && drop->params[1].default_value.value.integer == 0);
  assert(drop->params[1].option_count == 2 && equal(drop->params[1].options[0], "NOTE") && equal(drop->params[1].options[1], "STEP"));
  assert(equal(drop->params[2].name, "pattern_length") && drop->params[2].maximum.value.integer == 128);
  assert(equal(drop->params[3].name, "seed") && drop->params[3].maximum.value.integer == 10000);
}

void test_drop_behavior() {
  GlobalState global{};
  TransportView view{};
  RandomSource random{&g_seed, next_counter};
  const auto* drop = find_module("drop");
  ModuleState state{};
  drop->construct(state);
  NoteBatch input{}, output{};
  add_note(input.on, 60, 100, 0);
  add_note(input.on, 62, 90, 0);
  add_note(input.on, 64, 80, 0);
  add_note(input.on, 65, 70, 0);
  add_note(input.off, 60, 0, 0);
  add_note(input.off, 62, 0, 0);

  // Defaults: DROP=0 passes every on and off.
  auto ctx = make_context(global, view, random);
  drop->process(state, ctx, input, output);
  expect_pitches(output.on, {60, 62, 64, 65});
  expect_pitches(output.off, {60, 62});

  // Source fixture: DROP=50, MDE=NOTE, tick 0, SEED=0 drops only index 1 (seed 1 < 0.5).
  std::uint8_t effects = 0;
  assert(drop->set_param(state, 0, ParamValue::integer(50), global, effects));
  drop->process(state, ctx, input, output);
  expect_on(output.on, {{60, 100, 0}, {64, 80, 0}, {65, 70, 0}});
  // All note-offs pass through; source does not filter offs by dropped ons.
  expect_pitches(output.off, {60, 62});

  // DROP=100 drops every on and still passes every off.
  assert(drop->set_param(state, 0, ParamValue::integer(100), global, effects));
  drop->process(state, ctx, input, output);
  assert(output.on.count == 0);
  expect_pitches(output.off, {60, 62});

  // Source fixture: DROP=50, MDE=STEP, tick 12, SEED=3 keeps every note.
  assert(drop->set_param(state, 0, ParamValue::integer(50), global, effects));
  assert(drop->set_param(state, 1, ParamValue::integer(1), global, effects));
  assert(drop->set_param(state, 3, ParamValue::integer(3), global, effects));
  TransportView step_view{};
  step_view.tick = 12;
  auto step_ctx = make_context(global, step_view, random);
  drop->process(state, step_ctx, input, output);
  expect_pitches(output.on, {60, 62, 64, 65});

  // Source fixture: DROP=50, MDE=NOTE, tick 54, PTLEN=4, SEED=10 drops all four.
  assert(drop->set_param(state, 1, ParamValue::integer(0), global, effects));
  assert(drop->set_param(state, 2, ParamValue::integer(4), global, effects));
  assert(drop->set_param(state, 3, ParamValue::integer(10), global, effects));
  TransportView pattern_view{};
  pattern_view.tick = 54;
  auto pattern_ctx = make_context(global, pattern_view, random);
  drop->process(state, pattern_ctx, input, output);
  assert(output.on.count == 0);
  expect_pitches(output.off, {60, 62});

  // Range rejection: values outside the source bounds leave state unchanged.
  assert(!drop->set_param(state, 0, ParamValue::integer(101), global, effects));
  assert(!drop->set_param(state, 1, ParamValue::integer(2), global, effects));
  assert(!drop->set_param(state, 2, ParamValue::integer(129), global, effects));
  assert(!drop->set_param(state, 3, ParamValue::integer(10001), global, effects));
  assert(!drop->set_param(state, 0, ParamValue::boolean(true), global, effects));
  assert(!drop->set_param(state, 4, ParamValue::integer(0), global, effects));

  // Capacity boundary: twelve held ons at DROP=0 all pass; the batch is at source capacity.
  drop->construct(state);
  assert(drop->set_param(state, 0, ParamValue::integer(0), global, effects));
  NoteBatch full{};
  for (std::uint8_t n = 0; n < 12; ++n) add_note(full.on, static_cast<std::uint8_t>(40 + n), 100, 0);
  for (std::uint8_t n = 0; n < 12; ++n) add_note(full.off, static_cast<std::uint8_t>(40 + n), 0, 0);
  drop->process(state, ctx, full, output);
  assert(output.on.count == 12 && output.off.count == 12);
}

void test_randomize_defaults_and_params() {
  const auto* randomize = find_module("randomize");
  assert(randomize->version == 1 && randomize->param_count == 12);
  const char* names[] = {"velocity", "velocity_mode", "note", "note_increment", "note_chance", "note_mode",
                         "scale_aware", "octave", "octave_chance", "octave_mode", "pattern_length", "random_seed_user"};
  for (std::uint8_t i = 0; i < 12; ++i) assert(equal(randomize->params[i].name, names[i]));
  assert(randomize->params[0].default_value.value.integer == 0);
  assert(randomize->params[3].default_value.value.integer == 1 && randomize->params[3].minimum.value.integer == 1 &&
         randomize->params[3].maximum.value.integer == 128);
  assert(randomize->params[4].default_value.value.decimal == 0.5f);
  assert(randomize->params[4].type == ParamType::Decimal);
  assert(randomize->params[4].minimum.value.decimal == 0.0f && randomize->params[4].maximum.value.decimal == 1.0f);
  assert(randomize->params[6].default_value.value.boolean && !randomize->params[6].minimum.value.boolean);
  assert(randomize->params[8].default_value.value.decimal == 0.5f);
  assert(randomize->params[10].maximum.value.integer == 128);
  assert(randomize->params[11].maximum.value.integer == 10000);
}

void test_randomize_behavior() {
  GlobalState global{};
  TransportView view{};
  RandomSource random{&g_seed, next_counter};
  const auto* randomize = find_module("randomize");
  ModuleState state{};
  randomize->construct(state);
  NoteBatch input{}, output{};
  add_note(input.on, 60, 100, 0);
  add_note(input.on, 62, 90, 0);
  add_note(input.on, 64, 80, 0);
  add_note(input.on, 65, 70, 0);
  add_note(input.off, 60, 0, 0);
  add_note(input.off, 62, 0, 0);
  auto ctx = make_context(global, view, random);
  std::uint8_t effects = 0;

  // All ranges zero: note and velocity are unchanged and the off maps back.
  randomize->process(state, ctx, input, output);
  expect_on(output.on, {{60, 100, 0}, {62, 90, 0}, {64, 80, 0}, {65, 70, 0}});
  expect_on(output.off, {{60, 0, 0}, {62, 0, 0}});
  // The source keeps mappings for ons whose offs were not in the batch; reset
  // clears them so the following fixtures start from an empty relationship table.
  randomize->reset(state, ResetReason::Stop);

  // Source fixture: NTRNG=3, NTINC=2, UNI, INSCL=false, NTCHNC=0.5, tick 0, SEED=0.
  assert(randomize->set_param(state, 2, ParamValue::integer(3), global, effects));
  assert(randomize->set_param(state, 3, ParamValue::integer(2), global, effects));
  assert(randomize->set_param(state, 6, ParamValue::boolean(false), global, effects));
  randomize->process(state, ctx, input, output);
  expect_on(output.on, {{66, 100, 0}, {62, 90, 0}, {70, 80, 0}, {71, 70, 0}});
  expect_on(output.off, {{66, 0, 0}, {62, 0, 0}});
  // The two offs consumed the mappings for 60 and 62; 64 and 65 remain.
  assert(state.storage.randomize.relationships.count == 2);

  // Reset on Stop clears the remaining mappings, so their offs are silent.
  randomize->reset(state, ResetReason::Stop);
  assert(state.storage.randomize.relationships.count == 0);
  NoteBatch stale_off{};
  add_note(stale_off.off, 70, 0, 0);
  randomize->process(state, ctx, stale_off, output);
  assert(output.off.count == 0);

  // Source fixture: scale-aware octave randomization, OCRNG=2, OCCHNC=0.5, tick 0.
  randomize->reset(state, ResetReason::Stop);
  assert(randomize->set_param(state, 2, ParamValue::integer(0), global, effects));
  assert(randomize->set_param(state, 3, ParamValue::integer(1), global, effects));
  assert(randomize->set_param(state, 6, ParamValue::boolean(true), global, effects));
  assert(randomize->set_param(state, 7, ParamValue::integer(2), global, effects));
  randomize->process(state, ctx, input, output);
  expect_on(output.on, {{72, 100, 0}, {62, 90, 0}, {88, 80, 0}, {77, 70, 0}});
  expect_on(output.off, {{72, 0, 0}, {62, 0, 0}});
  randomize->reset(state, ResetReason::Stop);

  // Source fixture: VELRNG=10, VELMDE=BI, tick 5. Velocity is clamped to 0..127.
  assert(randomize->set_param(state, 7, ParamValue::integer(0), global, effects));
  assert(randomize->set_param(state, 2, ParamValue::integer(0), global, effects));
  assert(randomize->set_param(state, 0, ParamValue::integer(10), global, effects));
  assert(randomize->set_param(state, 1, ParamValue::integer(1), global, effects));
  assert(randomize->set_param(state, 6, ParamValue::boolean(false), global, effects));
  TransportView tick5{};
  tick5.tick = 5;
  auto tick5_ctx = make_context(global, tick5, random);
  randomize->process(state, tick5_ctx, input, output);
  expect_on(output.on, {{60, 105, 0}, {62, 94, 0}, {64, 72, 0}, {65, 64, 0}});
  randomize->reset(state, ResetReason::Stop);

  // Source fixture: NTRNG=4, NTINC=1, NTCHNC=1.0, NTMDE=BI, INSCL=true, key 2 scale MIN,
  // PTLEN=2, SEED=7, tick 13, VELRNG=0.
  assert(randomize->set_param(state, 0, ParamValue::integer(0), global, effects));
  assert(randomize->set_param(state, 1, ParamValue::integer(0), global, effects));
  assert(randomize->set_param(state, 2, ParamValue::integer(4), global, effects));
  assert(randomize->set_param(state, 3, ParamValue::integer(1), global, effects));
  assert(randomize->set_param(state, 4, ParamValue::decimal(1.0f), global, effects));
  assert(randomize->set_param(state, 5, ParamValue::integer(1), global, effects));
  assert(randomize->set_param(state, 6, ParamValue::boolean(true), global, effects));
  assert(randomize->set_param(state, 10, ParamValue::integer(2), global, effects));
  assert(randomize->set_param(state, 11, ParamValue::integer(7), global, effects));
  GlobalState key_global{};
  key_global.key = 2;
  key_global.scale = 2;
  TransportView tick13{};
  tick13.tick = 13;
  auto tick13_ctx = make_context(key_global, tick13, random);
  randomize->process(state, tick13_ctx, input, output);
  expect_on(output.on, {{64, 100, 0}, {67, 90, 0}, {65, 80, 0}, {64, 70, 0}});
  expect_on(output.off, {{64, 0, 0}, {67, 0, 0}});
  randomize->reset(state, ResetReason::Stop);

  // Source fixture: duplicate input pitch uses FIFO release mapping.
  assert(randomize->set_param(state, 2, ParamValue::integer(3), global, effects));
  assert(randomize->set_param(state, 3, ParamValue::integer(2), global, effects));
  assert(randomize->set_param(state, 4, ParamValue::decimal(0.5f), global, effects));
  assert(randomize->set_param(state, 5, ParamValue::integer(0), global, effects));
  assert(randomize->set_param(state, 6, ParamValue::boolean(false), global, effects));
  assert(randomize->set_param(state, 10, ParamValue::integer(0), global, effects));
  assert(randomize->set_param(state, 11, ParamValue::integer(0), global, effects));
  NoteBatch dup_on{}, dup_off{};
  add_note(dup_on.on, 60, 100, 0);
  add_note(dup_on.on, 60, 100, 0);
  add_note(dup_off.off, 60, 0, 0);
  add_note(dup_off.off, 60, 0, 0);
  randomize->process(state, ctx, dup_on, output);
  expect_on(output.on, {{66, 100, 0}, {60, 100, 0}});
  randomize->process(state, ctx, dup_off, output);
  expect_on(output.off, {{66, 0, 0}, {60, 0, 0}});
  randomize->reset(state, ResetReason::Stop);

  // Channel is carried from input to both on and off.
  NoteBatch ch{};
  add_note(ch.on, 60, 100, 5);
  randomize->process(state, ctx, ch, output);
  assert(output.on.count == 1 && output.on.items[0].channel == 5);
  add_note(ch.off, 60, 0, 5);
  randomize->process(state, ctx, ch, output);
  assert(output.off.count == 1 && output.off.items[0].channel == 5);
  randomize->reset(state, ResetReason::Stop);

  // Release-safety overflow: relationships hold 12; a 13th on is refused and counted.
  assert(randomize->set_param(state, 2, ParamValue::integer(0), global, effects));
  assert(randomize->set_param(state, 3, ParamValue::integer(1), global, effects));
  NoteBatch twelve{};
  for (std::uint8_t n = 0; n < 12; ++n) add_note(twelve.on, static_cast<std::uint8_t>(40 + n), 100, 0);
  randomize->process(state, ctx, twelve, output);
  assert(output.on.count == 12 && state.storage.randomize.relationships.count == 12);
  NoteBatch thirteenth{};
  add_note(thirteenth.on, 90, 100, 0);
  randomize->process(state, ctx, thirteenth, output);
  assert(output.on.count == 0 && state.storage.randomize.relationship_overflow == 1);
  assert(state.storage.randomize.relationships.count == 12);
  NoteBatch release_all{};
  for (std::uint8_t n = 0; n < 12; ++n) add_note(release_all.off, static_cast<std::uint8_t>(40 + n), 0, 0);
  randomize->process(state, ctx, release_all, output);
  assert(output.off.count == 12 && state.storage.randomize.relationships.count == 0);
  randomize->reset(state, ResetReason::Stop);

  // Range rejection.
  assert(!randomize->set_param(state, 3, ParamValue::integer(0), global, effects));
  assert(!randomize->set_param(state, 4, ParamValue::decimal(1.5f), global, effects));
  assert(!randomize->set_param(state, 4, ParamValue::integer(0), global, effects));
  assert(!randomize->set_param(state, 6, ParamValue::integer(1), global, effects));
  assert(!randomize->set_param(state, 11, ParamValue::integer(10001), global, effects));
  assert(!randomize->set_param(state, 12, ParamValue::integer(0), global, effects));
}

}  // namespace

int main() {
  test_hash_matches_source();
  test_drop_descriptor();
  test_drop_behavior();
  test_randomize_defaults_and_params();
  test_randomize_behavior();
  return 0;
}
